SELECT stage_before AS stage,mode,count() AS answers,countIf(rehab_active_before=false AND rehab_active_after=true) AS entries,entries/count() AS entry_rate,countIf(result='wrong')/count() AS wrong_rate FROM knowledge_analytics.training_answers WHERE review_credit=true AND $__timeFilter(occurred_at) AND (${mode:sqlstring}='__all' OR mode=${mode:sqlstring}) AND (${algorithm:sqlstring}='__all' OR algorithm_version=${algorithm:sqlstring}) AND (${experiment:sqlstring}='__all' OR experiment_group=${experiment:sqlstring}) GROUP BY stage,mode ORDER BY entries DESC
